import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import {
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  Input,
} from "@heroui/react";
import {
  CustomDatePicker,
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectAsyncSelect,
  CustomSelectReactSelect,
  CustomTextArea,
  Loading,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import { ToastContainer, toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

import "dayjs/locale/en-gb";
import { Modal } from "antd";
import { useStateContext } from "../../../contexts/ContextProvider";
import servicesApi from "../../../api/servicesApi";

export default function PhysiotherapyServicesFormModal({
  ismodalOpen,
  setisModalOpen,
  selectedPhysiotherapyService,
  modalTitle = "Add new retail inventory",
  updated,
  setUpdated,
}) {
  const moment = require("moment");
  const { currentColor } = useStateContext()


  const [errors, setErrors] = useState();




  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);
  const physiotherapyServiceApi = useApi(servicesApi.servicesAdminAction)
  const handleLaboratoryServiceAction = async (data) => {

    await physiotherapyServiceApi.request(data)
  }


  useEffect(() => {
    if (physiotherapyServiceApi.data) {
      if (physiotherapyServiceApi.data.physiotherapy_service) {
        toast.success(physiotherapyServiceApi.data.response_message)
        setUpdated(true)
        setisModalOpen(false)
      }


      if (physiotherapyServiceApi.data.errors) {
        setErrors(physiotherapyServiceApi.data.errors)
      }
    }
  }, [physiotherapyServiceApi.data])

  const formik = useFormik({
    initialValues: {

      title: selectedPhysiotherapyService ? selectedPhysiotherapyService.title : "",
      description: selectedPhysiotherapyService ? selectedPhysiotherapyService.description : "",

    },

    validationSchema: Yup.object({
      title: Yup.string().required().label("Title"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      let data = null;

      if (selectedPhysiotherapyService) {
        data = {
          "action": "UpdatePhysiotherapyService",
          "physiotherapy_service": selectedPhysiotherapyService.id,
          "title": values.title,
          "description": values.description,

        }
      } else {
        data = {
          "action": "CreatePhysiotherapyService",
          "title": values.title,
          "description": values.description,

        }

      }
      handleLaboratoryServiceAction(data)
      // resetForm();
    },
  });




  useEffect(() => {
    console.log("formik", formik.errors);
  }, [formik]);

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  return (
    <div className="w-full">
      <Modal
        width={600}
        className="w-full text-center"
        title={selectedPhysiotherapyService ? `EDIT ${selectedPhysiotherapyService.title}` : modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <div className="w-full grid grid-cols-1 mt-5 gap-1 ">

            <CustomFormItem
              touched={formik.touched.title}
              error={formik.errors.title}
            >
              <CustomInput
                className="uppercase"
                required={true}
                label="Enter title"
                id="title"
                name="title"
                onChange={formik.handleChange}
                placeholder="Enter title"
                size="large"
                type="text"
                value={formik.values.title}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.description}
              error={formik.errors.description}
            >
              <CustomTextArea
                required={true}
                label="Enter  description"
                id="description"
                name="description"
                onChange={formik.handleChange}
                placeholder="Enter  description"
                size="large"
                type="text"
                value={formik.values.description}
              />
            </CustomFormItem>
          </div>
          <div className="w-full items-center mt-2">
            <Button style={{ background: currentColor }} className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
