import React, { useEffect, useState } from "react";

import useApi from "../../../hooks/useApi";
import { useNavigate, useParams } from "react-router-dom";
import departmentsApi from "../../../api/departmentsApi";
import { Loading } from "../../../components";
import { useStateContext } from "../../../contexts/ContextProvider";
import logisticsApi from "../../../api/logistics/logisticsApi";
import PhysiotherapyServicesFormModal from "./PhysiotherapyServicesFormModal";
import PhysiotherapyServicesTable from "./PhysiotherapyServicesTable";
import servicesApi from "../../../api/servicesApi";

const columns = [
  { name: "Title", uid: "title" },
  { name: "Description", uid: "description" },
  { name: "Date", uid: "created" },
  { name: "Actions", uid: "actions" },
];

function PysiotherapyServicesList() {
  const [openInventoryFormModal, setopenInventoryFormModal] = useState(false);
  const navigate = useNavigate();
  const [selectedPhysiotherapyService, setselectedPhysiotherapyService] = useState();
  const [physiotherapyServices, setphysiotherapyServices] = useState([]);
  const [data, setdata] = useState([]);
  const [modalTitle, setmodalTitle] = useState("");
  const [updated, setUpdated] = useState(false);

  const physiotherapyServicesApi = useApi(servicesApi.servicesAdminAction);



  const getPhysiotherapyServices = async (data) => {

    await physiotherapyServicesApi.request({
      action: "GetPhysiotherapyServices",
     
    });
  };

  useEffect(() => {
    if (physiotherapyServicesApi.data) {
      if (physiotherapyServicesApi.data.length) {
        setphysiotherapyServices(physiotherapyServicesApi.data);
      }
    }
  }, [physiotherapyServicesApi.data]);

  useEffect(() => {

    getPhysiotherapyServices();


  }, []);

  useEffect(() => {
    setdata(physiotherapyServices);
  }, [physiotherapyServices]);

  const handleEditAction = (item) => {
    setopenInventoryFormModal(true);
    setselectedPhysiotherapyService(item);
    setmodalTitle(`EDIT ${item.title}`);
    setUpdated(false)
  };

  const handleAddAction = () => {
    setopenInventoryFormModal(true);
    setmodalTitle("Add new pathology service");
    setselectedPhysiotherapyService(null);
  };
  const handleDetailsAction = (item) => {
    navigate(`/systems/details/${item.id}`, {
      state: {
        item: item,
      },
    });
  };
  const handleDeleteAction = (item) => {
    console.log("Item", item);
    navigate(`/systems/delete/${item.id}`);
  };

  useEffect(() => {
    if (physiotherapyServicesApi.data && physiotherapyServicesApi.data.length) {
      setphysiotherapyServices(physiotherapyServicesApi.data);
    }
    console.log("getDepartmentsActionsApi.data", physiotherapyServicesApi.data);
  }, [physiotherapyServicesApi.data]);

  useEffect(() => {
    if (updated === true) {

      getPhysiotherapyServices();
    }
  }, [updated]);

  //Filtering data
  useEffect(() => {
    setdata(physiotherapyServices);
  }, [physiotherapyServices]);

  const handleFilter = (e) => {
    const search_param = e;
    if (
      physiotherapyServices &&
      physiotherapyServices.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        physiotherapyServices.filter((x) => x.title.toLowerCase().includes(search_param))
      );
    } else {
      setdata(physiotherapyServices);
    }
  };

  return physiotherapyServicesApi.loading ? (
    <Loading loading={departmentsApi.loading} />
  ) : (
    <div className="mt-16 md:mt-2">
        {openInventoryFormModal && (
          <PhysiotherapyServicesFormModal
            ismodalOpen={openInventoryFormModal}
            setisModalOpen={setopenInventoryFormModal}
            selectedPhysiotherapyService={selectedPhysiotherapyService}
            updated={updated}
            setUpdated={setUpdated}
            modalTitle={modalTitle}
          />
        )}

        <PhysiotherapyServicesTable
      title={"Physiotherapy Services"}
        data={data}
        columns={columns}
        editAction={handleEditAction}
        detailsAction={handleDetailsAction}
        deleteAction={handleDeleteAction}
        addAction={handleAddAction}
        handleFilter={handleFilter}
      />
    </div>
  );
}

export default PysiotherapyServicesList;
